css:
.d-ng{display:flex;flex-direction:column;align-items:flex-start;gap:8px}
.d-ng-art{display:block;width:168px;height:104px}
.d-ng-block{fill:#e8c34a}
.d-ng-film{animation:d-svg-noise-grain-jit 900ms steps(6) infinite}
.d-ng-grain{opacity:.38;mix-blend-mode:multiply}
@keyframes d-svg-noise-grain-jit{from{transform:translate(0,0)}to{transform:translate(6px,6px)}}
.d-ng-btn{font-family:var(--font-mono);font-size:var(--fs-11);letter-spacing:var(--tracking-mono-label);padding:8px 12px;border:1px solid var(--line);border-radius:6px;background:var(--paper);color:var(--muted);cursor:pointer}
.d-ng-btn:hover{border-color:var(--ink);color:var(--ink)}
.d-ng-btn:focus-visible{outline:1px solid var(--ink);outline-offset:2px}
@media (prefers-reduced-motion: reduce){.d-ng-film{animation:none}}

init:
root => {
    const box = root.querySelector('.d-ng'), btn = box.querySelector('.d-ng-btn');
    const turb = box.querySelector('feTurbulence');
    let fine = true;
    const apply = () => {
      turb.setAttribute('baseFrequency', fine ? '0.9' : '0.35');
      btn.textContent = fine ? '网点 细' : '网点 粗';
      btn.setAttribute('aria-pressed', String(!fine));
    };
    btn.onclick = () => { fine = !fine; apply(); };
    apply();
  }
